begin;
create index if not exists ingestion_external_lookup on public.lead_ingestion(source_id,external_lead_id) where external_lead_id<>'';
create index if not exists lead_phone_digits_lookup on public.leads(organization_id,(regexp_replace(mobile_no,'[^0-9]','','g')));
create table public.import_files(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,file_hash text not null,filename text not null,sheets jsonb not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),expires_at timestamptz not null default clock_timestamp()+interval '7 days',unique(organization_id,file_hash),unique(organization_id,id));
create table crm_private.import_file_content(file_id uuid primary key references public.import_files(id) on delete cascade,bytes bytea not null,parsed jsonb not null);
create table public.import_batches(id uuid primary key default gen_random_uuid(),organization_id uuid not null,file_id uuid not null,sheet_name text not null,source_id uuid not null,form_version text not null,config jsonb not null,revision integer not null default 1,state text not null default 'previewing' check(state in('previewing','ready','processing','completed','completed_with_errors','expired')),preview_cursor integer not null default 0,total integer not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),confirmed_at timestamptz,confirmed_by uuid references auth.users(id),unique(file_id,sheet_name),unique(organization_id,id),foreign key(organization_id,file_id) references public.import_files(organization_id,id) on delete cascade,foreign key(organization_id,source_id) references public.ingestion_sources(organization_id,id));
create table public.import_rows(organization_id uuid not null,batch_id uuid not null,row_number integer not null,state text not null check(state in('ready','invalid','excluded','imported','conflict','failed')),candidate jsonb not null,base_errors jsonb not null,errors jsonb not null,lead_id uuid references public.leads(id) on delete set null,imported_by uuid references auth.users(id),processed_at timestamptz,row_revision integer not null default 1,primary key(batch_id,row_number),foreign key(organization_id,batch_id) references public.import_batches(organization_id,id) on delete cascade);
create index import_rows_work on public.import_rows(batch_id,state,row_number);
create index import_external_preview on public.import_rows(batch_id,(candidate->>'external_id'));
create table public.source_external_identities(organization_id uuid not null,source_id uuid not null,external_key text not null check(length(external_key) between 1 and 200),lead_id uuid not null,batch_id uuid not null,primary key(source_id,external_key),foreign key(organization_id,source_id) references public.ingestion_sources(organization_id,id) on delete cascade,foreign key(organization_id,lead_id) references public.leads(organization_id,id) on delete cascade,foreign key(organization_id,batch_id) references public.import_batches(organization_id,id));
create table public.lead_import_provenance(lead_id uuid primary key,organization_id uuid not null,batch_id uuid not null,row_number integer not null,legacy_status text not null,legacy_caller text not null,source_at timestamptz,historical_confirmed boolean not null,confirmation_time_known boolean not null default false check(confirmation_time_known=false),confirmation_caller_known boolean not null default false check(confirmation_caller_known=false),unique(batch_id,row_number),foreign key(organization_id,lead_id) references public.leads(organization_id,id) on delete cascade,foreign key(organization_id,batch_id) references public.import_batches(organization_id,id));
alter table public.lead_edit_history drop constraint lead_edit_history_activity_type_check;
alter table public.lead_edit_history add constraint lead_edit_history_activity_type_check check(activity_type in('created','edit','call','imported'));
revoke all on crm_private.import_file_content from public,anon,authenticated,service_role;
do $$declare t text;begin foreach t in array array['import_files','import_batches','import_rows','source_external_identities'] loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant select on public.%I to authenticated',t);execute format('create policy admin_import_read on public.%I for select to authenticated using(exists(select 1 from public.organization_memberships m where m.organization_id=%I.organization_id and m.user_id=auth.uid() and m.active and m.role=''admin''))',t,t);end loop;end $$;
alter table public.lead_import_provenance enable row level security;revoke all on public.lead_import_provenance from public,anon,authenticated;grant select on public.lead_import_provenance to authenticated;
create policy provenance_read on public.lead_import_provenance for select to authenticated using(organization_id=(select public.lead_organization()));
create function crm_private.import_admin() returns uuid language plpgsql security definer set search_path='' as $$declare org uuid;begin select organization_id into org from public.organization_memberships where user_id=auth.uid() and active and role='admin' for share;if org is null then raise exception 'Admin required' using errcode='42501';end if;return org;end$$;
create function crm_private.expire_import_files(p_org uuid default null) returns integer language plpgsql security definer set search_path='' as $$declare n integer;begin
 delete from crm_private.import_file_content c using public.import_files f where c.file_id=f.id and f.expires_at<=clock_timestamp() and(p_org is null or f.organization_id=p_org);get diagnostics n=row_count;
 update public.import_rows r set candidate='{}',base_errors='[]',errors='[{"field":"file","code":"expired","message":"Staging expired; outcome retained."}]' where r.candidate<>'{}'::jsonb and exists(select 1 from public.import_batches b join public.import_files f on f.id=b.file_id where b.id=r.batch_id and f.expires_at<=clock_timestamp() and(p_org is null or f.organization_id=p_org));
 update public.import_batches b set state='expired' where b.state in('previewing','ready','processing') and exists(select 1 from public.import_files f where f.id=b.file_id and f.expires_at<=clock_timestamp()) and(p_org is null or b.organization_id=p_org);
 update public.import_files set filename='Expired upload',sheets='[]' where expires_at<=clock_timestamp() and filename<>'Expired upload' and(p_org is null or organization_id=p_org);return n;
end$$;
create function public.cleanup_import_staging() returns integer language sql security definer set search_path='' as $$select crm_private.expire_import_files(null)$$;
revoke all on function public.cleanup_import_staging() from public,anon,authenticated;grant execute on function public.cleanup_import_staging() to service_role;
create function public.import_housekeeping() returns integer language sql security definer set search_path='' as $$select crm_private.expire_import_files(crm_private.import_admin())$$;
revoke all on function public.import_housekeeping() from public,anon;grant execute on function public.import_housekeeping() to authenticated;
create function public.import_file_create(p_filename text,p_bytes text,p_parsed jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare org uuid:=crm_private.import_admin();data bytea;hash text;result uuid;meta jsonb;begin
 perform crm_private.expire_import_files(org);data=decode(p_bytes,'base64');if octet_length(data) not between 1 and 8388608 or octet_length(p_parsed::text)>30000000 or jsonb_typeof(p_parsed)<>'array' or jsonb_array_length(p_parsed) not between 1 and 20 or length(p_filename)>200 then raise exception 'Invalid upload bounds' using errcode='22023';end if;
 hash=encode(sha256(data),'hex');select jsonb_agg(jsonb_build_object('name',s->>'name','headers',s->'headers','total',jsonb_array_length(s->'rows'))) into meta from jsonb_array_elements(p_parsed)s;
 insert into public.import_files(organization_id,file_hash,filename,sheets,created_by)values(org,hash,p_filename,meta,auth.uid()) on conflict(organization_id,file_hash) do update set filename=excluded.filename,sheets=excluded.sheets,expires_at=clock_timestamp()+interval '7 days' returning id into result;
 insert into crm_private.import_file_content values(result,data,p_parsed) on conflict(file_id) do nothing;return result;
end$$;
create function public.import_file_slice(p_file uuid,p_sheet text,p_offset integer default 0,p_limit integer default 50,p_column integer default -1) returns jsonb language plpgsql security definer set search_path='' as $$declare org uuid:=crm_private.import_admin();s jsonb;begin
 perform crm_private.expire_import_files(org);if p_offset<0 or p_limit not between 1 and 100 or p_column not between -1 and 99 then raise exception 'Invalid bounds' using errcode='22023';end if;
 select x into s from public.import_files f join crm_private.import_file_content c on c.file_id=f.id cross join lateral jsonb_array_elements(c.parsed)x where f.id=p_file and f.organization_id=org and f.expires_at>clock_timestamp() and x->>'name'=p_sheet;if s is null then raise exception 'Upload unavailable or expired' using errcode='42501';end if;
 return jsonb_build_object('headers',s->'headers','total',jsonb_array_length(s->'rows'),'rows',coalesce((select jsonb_agg(v) from(select v from jsonb_array_elements(s->'rows') with ordinality q(v,n) where n>p_offset and n<=p_offset+p_limit)r),'[]'),'values',case when p_column<0 then '[]'::jsonb else (select coalesce(jsonb_agg(v),'[]') from(select distinct x->'cells'->p_column->>'text' v from jsonb_array_elements(s->'rows')x order by v limit 200)t) end);
end$$;
create function public.import_prepare(p_file uuid,p_sheet text,p_config jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare org uuid:=crm_private.import_admin();existing public.import_batches;sheet jsonb;source uuid;result uuid;begin
 perform crm_private.expire_import_files(org);source=(p_config->>'source_id')::uuid;
 if jsonb_typeof(p_config) is distinct from 'object' or p_config->>'acknowledged'<>'true' or not exists(select 1 from public.ingestion_sources where id=source and organization_id=org) or length(p_config->>'form_version')>80 then raise exception 'Confirm source/mappings' using errcode='22023';end if;
 select x into sheet from public.import_files f join crm_private.import_file_content c on c.file_id=f.id cross join lateral jsonb_array_elements(c.parsed)x where f.id=p_file and f.organization_id=org and f.expires_at>clock_timestamp() and x->>'name'=p_sheet;if sheet is null or jsonb_array_length(sheet->'rows')=0 then raise exception 'File unavailable/empty' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('import-prepare:'||p_file::text||p_sheet,0));select * into existing from public.import_batches where file_id=p_file and sheet_name=p_sheet for update;
 if found then if existing.config=p_config then return existing.id;end if;if existing.confirmed_at is not null then raise exception 'File/worksheet already confirmed; existing import preserved' using errcode='PT409';end if;
 delete from public.import_rows where batch_id=existing.id;update public.import_batches set config=p_config,source_id=source,form_version=p_config->>'form_version',revision=revision+1,preview_cursor=0,state='previewing' where id=existing.id;return existing.id;end if;
 insert into public.import_batches(organization_id,file_id,sheet_name,source_id,form_version,config,total,created_by)values(org,p_file,p_sheet,source,p_config->>'form_version',p_config,jsonb_array_length(sheet->'rows'),auth.uid())returning id into result;return result;
end$$;
create function crm_private.import_refresh_errors(p_batch uuid) returns void language plpgsql set search_path='' as $$declare b public.import_batches;begin
 select * into b from public.import_batches where id=p_batch;
 update public.import_rows r set errors=r.base_errors||case when coalesce(r.candidate->>'external_id','')<>'' and ((b.config->>'reliable_external')::boolean or not(b.config->>'allow_duplicate_metadata')::boolean) and (exists(select 1 from public.import_rows x where x.batch_id=p_batch and x.row_number<>r.row_number and x.state<>'excluded' and x.candidate->>'external_id'=r.candidate->>'external_id') or exists(select 1 from public.lead_ingestion i where i.source_id=b.source_id and i.external_lead_id=r.candidate->>'external_id')) then '[{"field":"external_id","code":"duplicate_external_id","message":"Duplicate/existing external ID: correct or explicitly exclude; existing CRM data is preserved."}]'::jsonb else '[]'::jsonb end where r.batch_id=p_batch and r.state in('ready','invalid','failed','conflict');
 update public.import_rows set state=case when jsonb_array_length(errors)=0 then 'ready' else 'invalid' end where batch_id=p_batch and state in('ready','invalid');
end$$;
create function public.import_preview_slice(p_batch uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare org uuid:=crm_private.import_admin();b public.import_batches;data jsonb;begin
 perform crm_private.expire_import_files(org);select * into b from public.import_batches where id=p_batch and organization_id=org;if not found or b.state not in('previewing','ready') then raise exception 'Preview unavailable' using errcode='42501';end if;
 data=public.import_file_slice(b.file_id,b.sheet_name,b.preview_cursor,100,-1);return data||jsonb_build_object('config',b.config,'cursor',b.preview_cursor,'revision',b.revision,'state',b.state);
end$$;
create function public.import_stage_rows(p_batch uuid,p_cursor integer,p_revision integer,p_rows jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare org uuid:=crm_private.import_admin();b public.import_batches;r jsonb;n integer:=0;begin
 select * into b from public.import_batches where id=p_batch and organization_id=org for update;if not found or b.confirmed_at is not null then raise exception 'Batch unavailable' using errcode='42501';end if;
 if b.revision<>p_revision then raise exception 'Mapping changed' using errcode='PT409';end if;if p_cursor<b.preview_cursor then return jsonb_build_object('replayed',true);end if;
 if b.state<>'previewing' or p_cursor<>b.preview_cursor or jsonb_typeof(p_rows)<>'array' or jsonb_array_length(p_rows) not between 1 and 100 or p_cursor+jsonb_array_length(p_rows)>b.total then raise exception 'Invalid preview chunk' using errcode='22023';end if;
 for r in select * from jsonb_array_elements(p_rows) loop
 if (r->>'row_number')::integer<>p_cursor+n+2 or jsonb_typeof(r->'errors')<>'array' or octet_length(r::text)>200000 then raise exception 'Invalid preview row' using errcode='22023';end if;
 insert into public.import_rows(organization_id,batch_id,row_number,state,candidate,base_errors,errors,lead_id,imported_by,processed_at) values(org,p_batch,(r->>'row_number')::integer,case when jsonb_array_length(r->'errors')=0 then 'ready' else 'invalid' end,r->'candidate',r->'errors',r->'errors',null,null,null);n=n+1;end loop;
 update public.import_batches set preview_cursor=preview_cursor+n,state=case when preview_cursor+n=total then 'ready' else 'previewing' end where id=b.id;
 if p_cursor+n=b.total then perform crm_private.import_refresh_errors(b.id);end if;return jsonb_build_object('previewed',p_cursor+n,'total',b.total);
end$$;
create function public.import_resolve_row(p_batch uuid,p_row integer,p_revision integer,p_result jsonb,p_exclude boolean,p_row_revision integer) returns void language plpgsql security definer set search_path='' as $$declare org uuid:=crm_private.import_admin();b public.import_batches;begin
 select * into b from public.import_batches where id=p_batch and organization_id=org for update;if not found or b.state='expired' or b.revision<>p_revision then raise exception 'Batch changed/unavailable' using errcode='PT409';end if;
 update public.import_rows set candidate=case when p_exclude then candidate else p_result->'candidate' end,base_errors=case when p_exclude then base_errors else p_result->'errors' end,errors=case when p_exclude then errors else p_result->'errors' end,row_revision=row_revision+1,state=case when p_exclude then 'excluded' when jsonb_array_length(p_result->'errors')=0 then 'ready' else 'invalid' end where batch_id=p_batch and row_number=p_row and state<>'imported' and row_revision=p_row_revision;if not found then raise exception 'Imported/unavailable row cannot be changed' using errcode='PT409';end if;
 perform crm_private.import_refresh_errors(p_batch);if b.confirmed_at is not null then update public.import_batches set state='processing' where id=p_batch;end if;
end$$;
create function public.import_confirm(p_batch uuid,p_revision integer) returns void language plpgsql security definer set search_path='' as $$declare org uuid:=crm_private.import_admin();b public.import_batches;begin
 perform crm_private.expire_import_files(org);select * into b from public.import_batches where id=p_batch and organization_id=org for update;if not found or b.revision<>p_revision then raise exception 'Batch changed/unavailable' using errcode='PT409';end if;
 if b.confirmed_at is not null then return;end if;if b.state<>'ready' or b.preview_cursor<>b.total then raise exception 'Complete preview first' using errcode='22023';end if;
 perform crm_private.import_refresh_errors(p_batch);if exists(select 1 from public.import_rows where batch_id=p_batch and state='invalid') then raise exception 'Correct or explicitly exclude invalid rows first' using errcode='22023';end if;
 update public.import_batches set state='processing',confirmed_at=clock_timestamp(),confirmed_by=auth.uid() where id=p_batch;
end$$;
-- Read-only public ingestion keeps its own receipt protection. A reliable external
-- identity claimed by a historical import becomes an explicit conflict, never a
-- silent duplicate or overwrite. Both paths serialize using the same source key.
alter function public.ingest_public_lead(text,uuid,text,jsonb,jsonb,jsonb) rename to ingest_public_lead_v6;
alter function public.ingest_public_lead_v6(text,uuid,text,jsonb,jsonb,jsonb) set schema crm_private;
revoke all on function crm_private.ingest_public_lead_v6(text,uuid,text,jsonb,jsonb,jsonb) from public,anon,authenticated,service_role;
create function public.ingest_public_lead(p_form text,p_submission uuid,p_origin text,p_original jsonb,p_lead jsonb,p_metadata jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare source uuid;ext text:=coalesce(p_metadata->>'external_lead_id','');begin
 select id into source from public.ingestion_sources where form_id=p_form;
 if ext<>'' and source is not null then perform pg_advisory_xact_lock(hashtextextended('source-external:'||source::text||ext,0));if exists(select 1 from public.source_external_identities where source_id=source and external_key=ext) then raise exception 'Reliable external identity was already imported; existing lead preserved' using errcode='PT409';end if;end if;
 return crm_private.ingest_public_lead_v6(p_form,p_submission,p_origin,p_original,p_lead,p_metadata);
end$$;
revoke all on function public.ingest_public_lead(text,uuid,text,jsonb,jsonb,jsonb) from public,anon,authenticated;grant execute on function public.ingest_public_lead(text,uuid,text,jsonb,jsonb,jsonb) to service_role;
create function public.import_process(p_batch uuid,p_limit integer default 100) returns jsonb language plpgsql security definer set search_path='' as $$
declare org uuid:=crm_private.import_admin();b public.import_batches;r public.import_rows;input jsonb;new_lead uuid;submission uuid;moment timestamptz;ext text;kind text;raw_row jsonb;staged_rows jsonb;heads jsonb;original_columns jsonb;answer jsonb;is_repeat boolean;processed integer:=0;begin
 perform crm_private.expire_import_files(org);if p_limit not between 1 and 100 then raise exception 'At most 100 rows' using errcode='22023';end if;
 if not exists(select 1 from public.import_batches where id=p_batch and organization_id=org) then raise exception 'Batch unavailable' using errcode='42501';end if;
 if not pg_try_advisory_xact_lock(hashtextextended('import-process:'||p_batch::text,0)) then return '{"busy":true}'::jsonb;end if;
 select * into b from public.import_batches where id=p_batch and organization_id=org for update;if not found or b.confirmed_at is null or b.state='expired' then raise exception 'Confirmed active batch required' using errcode='42501';end if;
 select x->'headers',x->'rows' into heads,staged_rows from crm_private.import_file_content c cross join lateral jsonb_array_elements(c.parsed)x where c.file_id=b.file_id and x->>'name'=b.sheet_name;
 for r in select * from public.import_rows where batch_id=p_batch and state='ready' order by row_number limit p_limit for update loop
 begin
 input=r.candidate;ext=coalesce(input->>'external_id','');
 if not exists(select 1 from public.lead_statuses where organization_id=org and id=(input->>'status_id')::uuid and active) then raise exception 'Invalid mapped status' using errcode='22023';end if;
 perform crm_private.validate_lead_input(jsonb_build_object('name',input->>'name','mobile_no',input->>'mobile_no','address',input->>'address','answers',input->'answers'));
 if (b.config->>'reliable_external')::boolean then
 if ext='' then raise exception 'Reliable identity missing' using errcode='22023';end if;perform pg_advisory_xact_lock(hashtextextended('source-external:'||b.source_id::text||ext,0));
 if exists(select 1 from public.source_external_identities where source_id=b.source_id and external_key=ext) or exists(select 1 from public.lead_ingestion where source_id=b.source_id and external_lead_id=ext) then raise exception 'Existing reliable external identity; no overwrite' using errcode='PT409';end if;
 end if;
 submission=case when(b.config->>'reliable_external')::boolean and ext~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then ext::uuid else gen_random_uuid() end;
 perform pg_advisory_xact_lock(hashtextextended('ingest:'||b.source_id::text||submission::text,0));if exists(select 1 from public.lead_ingestion where source_id=b.source_id and submission_id=submission) then raise exception 'Existing source submission; no overwrite' using errcode='PT409';end if;
 raw_row=staged_rows->(r.row_number-2);if raw_row is null then raise exception 'Staging expired' using errcode='42501';end if;
 select jsonb_agg(jsonb_build_object('position',(h->>'position')::integer,'heading',h->>'heading','label',b.config->'columns'->((h->>'position')::integer)->>'label','value',raw_row->'cells'->((h->>'position')::integer)->>'text','kind',raw_row->'cells'->((h->>'position')::integer)->>'kind') order by (h->>'position')::integer) into original_columns from jsonb_array_elements(heads)h;
 moment=clock_timestamp();perform pg_advisory_xact_lock(hashtextextended('ingest-phone:'||org::text||regexp_replace(input->>'mobile_no','[^0-9]','','g'),0));is_repeat=exists(select 1 from public.leads where organization_id=org and regexp_replace(mobile_no,'[^0-9]','','g')=regexp_replace(input->>'mobile_no','[^0-9]','','g'));
 insert into public.leads(organization_id,name,mobile_no,address,answers,status_id,created_by,created_at,updated_at)values(org,input->>'name',input->>'mobile_no',input->>'address',input->'answers',(input->>'status_id')::uuid,null,moment,moment)returning id into new_lead;
 update public.lead_edit_history set activity_type='imported',editor_id=null where lead_id=new_lead and version=1;
 answer=input->'answers';insert into public.lead_ingestion(lead_id,organization_id,source_id,submission_id,received_at,external_lead_id,source_timestamp,original_submission,original_answers,raw_advertising,normalized_attribution,source_snapshot,legacy_otp_label,is_repeat)values(new_lead,org,b.source_id,submission,moment,ext,coalesce(input->>'source_timestamp',''),jsonb_build_object('import_batch',b.id,'row_number',r.row_number,'columns',original_columns,'corrections',input->'corrections','legacy',input->'legacy'),answer,coalesce(input->'tracking','{}'),'{}',jsonb_build_object('form_id',(select form_id from public.ingestion_sources where id=b.source_id),'form_version',b.form_version,'import_batch',b.id,'historical',true),input->'legacy_otp',is_repeat);
 select category into kind from public.lead_statuses where id=(input->>'status_id')::uuid;
 insert into public.lead_import_provenance(lead_id,organization_id,batch_id,row_number,legacy_status,legacy_caller,source_at,historical_confirmed)values(new_lead,org,b.id,r.row_number,coalesce(input->>'legacy_status',''),coalesce(input->>'legacy_caller',''),nullif(input->>'source_at','')::timestamptz,kind='confirmed');
 if(b.config->>'reliable_external')::boolean then insert into public.source_external_identities values(org,b.source_id,ext,new_lead,b.id);end if;
 update public.import_rows set state='imported',lead_id=new_lead,processed_at=moment,imported_by=auth.uid() where batch_id=b.id and row_number=r.row_number;
 exception when others then update public.import_rows set state=case when SQLSTATE='PT409' then 'conflict' else 'failed' end,errors=jsonb_build_array(jsonb_build_object('field','row','code',case when SQLSTATE='PT409' then 'identity_conflict' else 'transaction_failed' end,'message','No partial row committed; existing data preserved. Review/correct or exclude before retry.')) where batch_id=b.id and row_number=r.row_number;end;
 processed=processed+1;
 end loop;
 update public.import_batches set state=case when exists(select 1 from public.import_rows where batch_id=b.id and state='ready') then 'processing' when exists(select 1 from public.import_rows where batch_id=b.id and state in('invalid','failed','conflict')) then 'completed_with_errors' else 'completed' end where id=b.id;
 return jsonb_build_object('processed',processed,'busy',false);
end$$;
create function public.import_batch_read(p_batch uuid,p_page integer default 1) returns jsonb language plpgsql security definer set search_path='' as $$declare org uuid:=crm_private.import_admin();b public.import_batches;data jsonb;raw_sheet jsonb;begin
 perform crm_private.expire_import_files(org);select * into b from public.import_batches where id=p_batch and organization_id=org;if not found or p_page<1 or p_page>1000 then raise exception 'Batch unavailable' using errcode='42501';end if;
 select x into raw_sheet from crm_private.import_file_content c cross join lateral jsonb_array_elements(c.parsed)x where c.file_id=b.file_id and x->>'name'=b.sheet_name;
 select jsonb_build_object('total',count(*),'imported',count(*)filter(where state='imported'),'invalid',count(*)filter(where state='invalid'),'excluded',count(*)filter(where state='excluded'),'ready',count(*)filter(where state='ready'),'failed',count(*)filter(where state='failed'),'conflict',count(*)filter(where state='conflict')) into data from public.import_rows where batch_id=b.id;
 return jsonb_build_object('batch',to_jsonb(b),'counts',data,'rows',coalesce((select jsonb_agg(to_jsonb(q)||jsonb_build_object('raw',raw_sheet->'rows'->(q.row_number-2))) from(select * from public.import_rows where batch_id=b.id order by row_number limit 50 offset(p_page-1)*50)q),'[]'),'page',p_page);
end$$;
-- Privileged internal helpers are not client-callable. Public RPCs derive scope.
revoke all on function crm_private.import_admin(),crm_private.expire_import_files(uuid),crm_private.import_refresh_errors(uuid) from public,anon,authenticated,service_role;
revoke all on function public.import_file_create(text,text,jsonb),public.import_file_slice(uuid,text,integer,integer,integer),public.import_prepare(uuid,text,jsonb),public.import_preview_slice(uuid),public.import_stage_rows(uuid,integer,integer,jsonb),public.import_resolve_row(uuid,integer,integer,jsonb,boolean,integer),public.import_confirm(uuid,integer),public.import_process(uuid,integer),public.import_batch_read(uuid,integer) from public,anon;
grant execute on function public.import_file_create(text,text,jsonb),public.import_file_slice(uuid,text,integer,integer,integer),public.import_prepare(uuid,text,jsonb),public.import_preview_slice(uuid),public.import_stage_rows(uuid,integer,integer,jsonb),public.import_resolve_row(uuid,integer,integer,jsonb,boolean,integer),public.import_confirm(uuid,integer),public.import_process(uuid,integer),public.import_batch_read(uuid,integer) to authenticated;
notify pgrst,'reload schema';commit;
